// Small, serializable games. No timers, DOM, renderer or world actors are owned
// here: the game's existing capped loop advances only the currently open game.
import {karaokeTrack} from './karaoke-tracks.js';
export const gameNames={karaoke:'卡拉 OK',rhythm:'霓虹节拍',race:'环城冲刺',claw:'抓海豚娃娃',breaker:'街机打砖块',mahjong:'八张麻将速局',poker:'德州扑克速局',billiards:'六球台球挑战'};
export const gamePrices={karaoke:12,rhythm:6,race:8,claw:5,breaker:5,mahjong:10,poker:15,billiards:10};
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function random(seed){let s=seed>>>0;return()=>((s=(s*1664525+1013904223)>>>0)/4294967296);}
function shuffle(a,rng){for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function mahjongWin(tiles){if(tiles.length!==8)return false;const counts=Array(27).fill(0);for(const t of tiles){if(!Number.isInteger(t)||t<0||t>26)return false;counts[t]++;}function melds(){const i=counts.findIndex(n=>n>0);if(i<0)return true;if(counts[i]>=3){counts[i]-=3;const ok=melds();counts[i]+=3;if(ok)return true;}if(i%9<=6&&counts[i+1]&&counts[i+2]){counts[i]--;counts[i+1]--;counts[i+2]--;const ok=melds();counts[i]++;counts[i+1]++;counts[i+2]++;if(ok)return true;}return false;}for(let i=0;i<27;i++)if(counts[i]>=2){counts[i]-=2;const ok=melds();counts[i]+=2;if(ok)return true;}return false;}
export function pokerValue(cards){let best=[];function score(c){const ranks=c.map(n=>n%13+2).sort((a,b)=>b-a),suits=c.map(n=>Math.floor(n/13)),counts=new Map();for(const n of ranks)counts.set(n,(counts.get(n)||0)+1);const groups=[...counts].sort((a,b)=>b[1]-a[1]||b[0]-a[0]),unique=[...new Set(ranks)];if(unique[0]===14)unique.push(1);let straight=0;for(let i=0;i<=unique.length-5;i++)if(unique[i]-unique[i+4]===4){straight=unique[i];break;}const flush=suits.every(n=>n===suits[0]);if(flush&&straight)return[8,straight];if(groups[0][1]===4)return[7,groups[0][0],groups[1][0]];if(groups[0][1]===3&&groups[1][1]===2)return[6,groups[0][0],groups[1][0]];if(flush)return[5,...ranks];if(straight)return[4,straight];if(groups[0][1]===3)return[3,groups[0][0],...groups.slice(1).map(g=>g[0])];if(groups[0][1]===2&&groups[1][1]===2)return[2,Math.max(groups[0][0],groups[1][0]),Math.min(groups[0][0],groups[1][0]),groups[2][0]];if(groups[0][1]===2)return[1,groups[0][0],...groups.slice(1).map(g=>g[0])];return[0,...ranks];}function choose(start,a){if(a.length===5){const v=score(a);if(compareHands(v,best)>0)best=v;return;}for(let i=start;i<=cards.length-(5-a.length);i++)choose(i+1,[...a,cards[i]]);}choose(0,[]);return best;}
export function compareHands(a,b){for(let i=0;i<Math.max(a.length,b.length);i++){const d=(a[i]||0)-(b[i]||0);if(d)return Math.sign(d);}return 0;}
export const pokerLabels=['高牌','一对','两对','三条','顺子','同花','葫芦','四条','同花顺'];

export function createRound(type,seed=1,track=0){const rng=random(seed),a={type,seed,time:0,score:0,done:false,paid:gamePrices[type]||0,room:null};
 if(type==='karaoke'||type==='rhythm'){const song=karaokeTrack(track),bpm=type==='karaoke'?song.bpm:[104,116,128][track%3],beats=type==='karaoke'?song.beats:Array.from({length:32},(_,i)=>2+i*60/bpm);Object.assign(a,{track,bpm,notes:beats.map((at,i)=>({at,lane:(i*3+Math.floor(i/4)+track)%4,judged:false,hit:false})),hits:0,combo:0,bestCombo:0,feedback:'准备 · 跟着节拍',duration:beats.at(-1)+1});if(type==='karaoke')Object.assign(a,{songId:song.id,audioVersion:1});}
 else if(type==='race')Object.assign(a,{duration:32,x:320,offset:0,obstacles:Array.from({length:24},(_,i)=>({at:2+i*1.22,lane:80+Math.floor(rng()*5)*120,passed:false})),crashes:0,distance:0,stun:0});
 else if(type==='claw')Object.assign(a,{duration:28,x:320,y:185,phase:'aim',drop:0,toys:Array.from({length:8},(_,i)=>({x:110+(i%4)*135+(rng()-.5)*30,y:135+Math.floor(i/4)*95+(rng()-.5)*24,color:i%3})),caught:-1});
 else if(type==='breaker')Object.assign(a,{duration:40,paddle:320,ball:{x:320,y:285,vx:165,vy:-235},lives:3,blocks:Array.from({length:24},(_,i)=>({x:76+(i%8)*69,y:57+Math.floor(i/8)*29,alive:true})),launched:false});
 else if(type==='mahjong'){const suit=Math.floor(rng()*3)*9,start=Math.floor(rng()*3),goal=[suit+start,suit+start+1,suit+start+2,suit+start+3,suit+start+4,suit+start+5,suit+7,suit+7],missing=goal.splice(Math.floor(rng()*6),1)[0];const junk=(suit+9+Math.floor(rng()*9))%27;const hand=[...goal,junk].sort((a,b)=>a-b),wall=shuffle(Array.from({length:108},(_,i)=>Math.floor(i/4)).filter((t,i,all)=>{const used=hand.filter(n=>n===t).length;return i%4>=used;}),rng);const index=wall.indexOf(missing);if(index>=0){wall.splice(index,1);wall.splice(2+Math.floor(rng()*4),0,missing);}Object.assign(a,{hand,wall,discards:[],draws:0,maxDraws:12,lastDraw:null,feedback:'弃一摸一 · 两组面子加一对即可和牌'});}
 else if(type==='poker'){const deck=shuffle(Array.from({length:52},(_,i)=>i),rng);Object.assign(a,{hand:deck.splice(0,2),opponent:deck.splice(0,2),community:deck.splice(0,5),street:0,shown:3,pot:30,toCall:0,raised:false,aiBets:[rng()<.4,rng()<.4,rng()<.4],feedback:'翻牌 · 可以过牌、加注或弃牌'});if(a.aiBets[0]){a.toCall=5;a.pot+=5;}}
 else if(type==='billiards')Object.assign(a,{shots:0,maxShots:8,angle:-.2,power:.6,moving:false,balls:[{x:150,y:180,vx:0,vy:0,cue:true,pocket:false},...Array.from({length:6},(_,i)=>({x:405+Math.floor(i/3)*20,y:155+(i%3)*25,vx:0,vy:0,cue:false,pocket:false,color:i}))],feedback:'瞄准彩球 · 拖动球杆 / A D 调角度 · 空格击球'});
 return a;
}
export function roundPayout(a){if(!a.done)return 0;if(a.type==='karaoke'||a.type==='rhythm'){const accuracy=a.hits/a.notes.length;return accuracy>=.85?a.paid+24:accuracy>=.6?a.paid+10:accuracy>=.35?4:0;}if(a.type==='race')return a.crashes<=2?32:a.crashes<=5?18:6;if(a.type==='claw')return a.caught>=0?18:0;if(a.type==='breaker')return a.score*2;if(a.type==='mahjong')return a.win?28:0;if(a.type==='poker')return a.folded?0:a.result===1?a.pot:a.result===0?Math.floor(a.pot/2):0;if(a.type==='billiards')return a.score*6;return 0;}
export function inputRound(a,action,value){if(!a||a.done)return false;
 if(a.type==='karaoke'||a.type==='rhythm'){if(action!=='lane')return false;const candidates=a.notes.filter(n=>!n.judged&&n.lane===value).sort((x,y)=>Math.abs(x.at-a.time)-Math.abs(y.at-a.time)),n=candidates[0],error=n?Math.abs(n.at-a.time):Infinity;if(error<=.22){n.hit=n.judged=true;a.hits++;a.combo++;a.bestCombo=Math.max(a.bestCombo,a.combo);a.score+=error<.09?100:70;a.feedback=error<.09?'PERFECT':'GOOD';return true;}a.combo=0;a.feedback='早了或晚了';return false;}
 if(a.type==='claw'){if(a.phase!=='aim')return false;if(action==='aim'){a.x=clamp(value.x,55,585);a.y=clamp(value.y,95,275);}if(action==='drop'){a.phase='drop';a.drop=0;}return true;}
 if(a.type==='breaker'){if(action==='aim')a.paddle=clamp(value.x,55,585);if(action==='shoot')a.launched=true;return true;}
 if(a.type==='race'){if(action==='aim')a.x=clamp(value.x,52,588);return true;}
 if(a.type==='mahjong'){if(action==='hu'){if(!mahjongWin(a.hand)){a.feedback='还差一点：需要两组三张面子和一对';return false;}a.win=a.done=true;return true;}if(action!=='discard'||!Number.isInteger(value)||value<0||value>=a.hand.length||a.draws>=a.maxDraws)return false;a.discards.push(a.hand.splice(value,1)[0]);a.lastDraw=a.wall.shift();a.hand.push(a.lastDraw);a.hand.sort((x,y)=>x-y);a.draws++;a.feedback=mahjongWin(a.hand)?'可以和牌！':`已摸 ${a.draws}/${a.maxDraws} 手`;if(a.draws>=a.maxDraws&&!mahjongWin(a.hand))a.done=true;return true;}
 if(a.type==='poker'){if(action==='fold'){a.folded=a.done=true;return true;}if(action!=='advance')return false;if(a.street===2){const p=pokerValue([...a.hand,...a.community]),q=pokerValue([...a.opponent,...a.community]);a.result=compareHands(p,q);a.handName=pokerLabels[p[0]];a.opponentName=pokerLabels[q[0]];a.done=true;return true;}a.street++;a.shown++;a.raised=false;a.toCall=a.aiBets[a.street]?5:0;a.pot+=a.toCall;return true;}
 if(a.type==='billiards'){if(a.moving)return false;if(action==='aim'){const cue=a.balls[0];a.angle=Math.atan2(value.y-cue.y,value.x-cue.x);}if(action==='power')a.power=clamp(value,.15,1);if(action==='shoot'){if(a.shots>=a.maxShots)return false;const cue=a.balls[0];cue.vx=Math.cos(a.angle)*(170+a.power*390);cue.vy=Math.sin(a.angle)*(170+a.power*390);a.shots++;a.moving=true;}return true;}
 return false;
}
export function advanceRound(a,dt,controls={},mediaTime){if(!a||a.done||!Number.isFinite(dt)||dt<=0)return;dt=Math.min(dt,.05);controls={left:Number(!!controls.left),right:Number(!!controls.right),up:Number(!!controls.up),down:Number(!!controls.down)};if(a.type==='karaoke'&&Number.isFinite(mediaTime))a.time=Math.max(a.time,Math.min(a.duration,mediaTime));else a.time+=dt;
 if(a.type==='karaoke'||a.type==='rhythm'){for(const n of a.notes)if(!n.judged&&a.time>n.at+.22){n.judged=true;a.combo=0;a.feedback='MISS';}if(a.time>=a.duration)a.done=true;}
 else if(a.type==='race'){a.x=clamp(a.x+(controls.right-controls.left)*dt*330,52,588);a.distance+=dt*(a.stun>0?14:32);a.stun=Math.max(0,a.stun-dt);for(const o of a.obstacles)if(!o.passed&&a.time>o.at){o.passed=true;if(Math.abs(o.lane-a.x)<58){a.crashes++;a.stun=.7;}}a.score=Math.floor(a.distance);if(a.time>=a.duration)a.done=true;}
 else if(a.type==='claw'){if(a.phase==='aim'){a.x=clamp(a.x+(controls.right-controls.left)*dt*170,55,585);a.y=clamp(a.y+(controls.down-controls.up)*dt*130,95,275);if(a.time>a.duration){a.phase='drop';a.drop=0;}}else{a.drop+=dt;if(a.drop>=2){let best=Infinity;for(let i=0;i<a.toys.length;i++){const d=Math.hypot(a.toys[i].x-a.x,(a.toys[i].y-a.y)*1.1);if(d<best){best=d;a.caught=i;}}if(best>24)a.caught=-1;a.score=a.caught>=0?1:0;a.done=true;}}}
 else if(a.type==='breaker'){a.paddle=clamp(a.paddle+(controls.right-controls.left)*dt*430,55,585);const b=a.ball;if(!a.launched){b.x=a.paddle;b.y=285;}else for(let i=0;i<4;i++){const h=dt/4;b.x+=b.vx*h;b.y+=b.vy*h;if(b.x<15||b.x>625){b.x=clamp(b.x,15,625);b.vx=-b.vx;}if(b.y<15){b.y=15;b.vy=Math.abs(b.vy);}if(b.vy>0&&b.y>=287&&b.y<304&&Math.abs(b.x-a.paddle)<53){b.vy=-Math.abs(b.vy);b.vx=(b.x-a.paddle)*5.2;b.y=285;}for(const block of a.blocks)if(block.alive&&Math.abs(b.x-block.x)<33&&Math.abs(b.y-block.y)<18){block.alive=false;a.score++;b.vy=-b.vy;break;}if(b.y>365){a.lives--;a.launched=false;b.vx=165;b.vy=-235;if(a.lives<=0)a.done=true;break;}}if(a.time>=a.duration||a.blocks.every(b=>!b.alive))a.done=true;}
 else if(a.type==='billiards'){if(!a.moving){if(controls.left||controls.right)a.angle+=(controls.right-controls.left)*dt*1.4;return;}const pockets=[[32,40],[320,40],[608,40],[32,320],[320,320],[608,320]],steps=Math.ceil(dt/.008),h=dt/steps;for(let step=0;step<steps;step++){for(const b of a.balls){if(b.pocket)continue;b.x+=b.vx*h;b.y+=b.vy*h;b.vx*=Math.exp(-h*.8);b.vy*=Math.exp(-h*.8);if(pockets.some(p=>Math.hypot(b.x-p[0],b.y-p[1])<22)){b.pocket=true;b.vx=b.vy=0;if(!b.cue)a.score++;continue;}if(b.x<42||b.x>598){b.x=clamp(b.x,42,598);b.vx=-b.vx*.87;}if(b.y<50||b.y>310){b.y=clamp(b.y,50,310);b.vy=-b.vy*.87;}}
   for(let i=0;i<a.balls.length;i++)for(let j=i+1;j<a.balls.length;j++){const p=a.balls[i],q=a.balls[j];if(p.pocket||q.pocket)continue;const dx=q.x-p.x,dy=q.y-p.y,d=Math.hypot(dx,dy);if(d>=16||d<1e-6)continue;const ux=dx/d,uy=dy/d,over=(16-d)/2;p.x-=ux*over;p.y-=uy*over;q.x+=ux*over;q.y+=uy*over;const approach=(p.vx-q.vx)*ux+(p.vy-q.vy)*uy;if(approach>0){p.vx-=approach*ux;p.vy-=approach*uy;q.vx+=approach*ux;q.vy+=approach*uy;}}
  }if(a.balls.every(b=>b.pocket||Math.hypot(b.vx,b.vy)<4)){for(const b of a.balls)b.vx=b.vy=0;a.moving=false;if(a.balls[0].pocket){Object.assign(a.balls[0],{x:150,y:180,pocket:false});a.feedback='白球落袋 · 已放回开球点';}if(a.score>=6||a.shots>=a.maxShots)a.done=true;}}
}
